/* ==UserStyle==
@name Hacker News Oxide
@namespace github.com/oxidescheme/userstyles/styles/hackernews
@homepageURL https://github.com/oxidescheme/userstyles/tree/main/styles/hackernews
@version 2025.05.10
@updateURL https://github.com/oxidescheme/userstyles/raw/main/styles/hackernews/oxide.user.less
@supportURL https://github.com/oxidescheme/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Ahackernews
@description Oxide dark theme for Hacker News
@author Oxide
@license MIT
@preprocessor less
==/UserStyle== */

@import "https://raw.githubusercontent.com/oxidescheme/userstyles/main/lib/lib.less";

@-moz-document domain("news.ycombinator.com") {
    #lib.palette();
    #lib.defaults();

    body {
        background-color: @mantle;
    }

    // --- Main container ---
    #hnmain {
        background-color: @base;
    }

    // --- Header bar (orange bar) ---
    td[bgcolor="#ff6600"] {
        background-color: @surface1 !important;
    }

    .pagetop {
        color: @text;
    }

    .pagetop a:link,
    .pagetop a:visited {
        color: @text;
    }

    .pagetop a:hover {
        color: @accent;
    }

    .topsel a:link,
    .topsel a:visited {
        color: @bright_text !important;
    }

    .hnname a {
        color: @accent !important;
    }

    // --- Story rows ---
    .title {
        color: @subtext1;
    }

    .title a:link {
        color: @text;
    }

    .title a:visited {
        color: @subtext1;
    }

    .title a:hover {
        color: @accent;
    }

    .sitebit.comhead {
        color: @subtext1;
    }

    .sitestr {
        color: @accent;
    }

    // --- Subtext (points, author, time, comments) ---
    .subtext {
        color: @subtext1;
    }

    .subtext a:link,
    .subtext a:visited {
        color: @subtext0;
    }

    .subtext a:hover {
        color: @accent;
    }

    .score {
        color: @subtext0;
    }

    .hnuser {
        color: @accent;
    }

    .hnuser:visited {
        color: @purple;
    }

    .age a {
        color: @subtext0;
    }

    // --- Vote arrows ---
    .votearrow {
        filter: invert(1) brightness(0.7);
    }

    .votearrow.rotate180 {
        filter: invert(1) brightness(0.4);
    }

    // --- Comment pages ---
    .comment {
        color: @text;
    }

    .comment a:link {
        color: @accent;
    }

    .comment a:visited {
        color: @purple;
    }

    .comhead {
        color: @subtext1;
    }

    .comhead a:link {
        color: @subtext0;
    }

    .comhead a:visited {
        color: @subtext1;
    }

    // Comment age colors (map to oxide text hierarchy)
    .c00, .c00 a:link { color: @text; }
    .c5a, .c5a a:link { color: @subtext0; }
    .c73, .c73 a:link { color: @subtext0; }
    .c82, .c82 a:link { color: @subtext1; }
    .c88, .c88 a:link { color: @subtext1; }
    .c9c, .c9c a:link { color: @subtext1; }
    .cae, .cae a:link { color: @subtext2; }
    .cbe, .cbe a:link { color: @subtext2; }
    .cce, .cce a:link { color: @subtext2; }
    .cdd, .cdd a:link { color: @subtext2; }

    // --- Default text ---
    .default {
        color: @text;
    }

    // --- Admin text ---
    .admin {
        color: @bright_text;
    }

    .admin a:link {
        color: @accent;
    }

    // --- Forms (login, submit, etc.) ---
    textarea,
    input[type="text"],
    input[type="password"],
    input[name="q"] {
        background-color: @surface0;
        color: @text;
        border: 1px solid @surface1;
    }

    textarea:focus,
    input[type="text"]:focus,
    input[type="password"]:focus {
        border-color: @accent;
    }

    input[type="submit"] {
        background-color: @surface1;
        color: @text;
        border: 1px solid @subtext2;
        padding: 2px 8px;
    }

    input[type="submit"]:hover {
        background-color: @surface0;
        border-color: @accent;
        color: @accent;
    }

    // --- More link (pagination) ---
    a.morelink {
        color: @accent;
    }

    a.morelink:visited {
        color: @purple;
    }

    // --- Footer ---
    .yclinks {
        color: @subtext1;
    }

    .yclinks a {
        color: @subtext0;
    }

    .yclinks a:hover {
        color: @accent;
    }

    // Footer separator line
    td[bgcolor="#ff6600"] {
        background-color: @surface1 !important;
    }

    // --- Polls ---
    .poll a:link {
        color: @accent;
    }

    .poll a:visited {
        color: @purple;
    }

    // --- Misc ---
    a:link {
        color: @accent;
    }

    a:visited {
        color: @purple;
    }

    .cdd a:visited {
        color: @subtext2;
    }

    // Spacer rows
    tr.spacer {
        background-color: @base;
    }
}

/* ==UserStyle==
@name Wikipedia Oxide
@namespace github.com/oxidescheme/userstyles/styles/wikipedia
@homepageURL https://github.com/oxidescheme/userstyles/tree/main/styles/wikipedia
@version 2025.05.10
@updateURL https://github.com/oxidescheme/userstyles/raw/main/styles/wikipedia/oxide.user.less
@supportURL https://github.com/oxidescheme/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Awikipedia
@description Oxide dark theme for Wikipedia
@author Oxide
@license MIT
@preprocessor less
==/UserStyle== */

@import "https://raw.githubusercontent.com/oxidescheme/userstyles/main/lib/lib.less";

@-moz-document domain("wikipedia.org"), domain("wikimedia.org") {
    #lib.palette();
    #lib.defaults();

    // --- Override Codex design tokens (the primary theming mechanism) ---
    // Force dark regardless of user preference
    html,
    html.skin-theme-clientpref-day,
    html.skin-theme-clientpref-night,
    html.skin-theme-clientpref-os {
        // Text colors
        --color-base: @text;
        --color-base-fixed: @text;
        --color-base--hover: @bright_text;
        --color-emphasized: @bright_text;
        --color-neutral: @subtext0;
        --color-subtle: @subtext1;
        --color-inverted: @base;
        --color-inverted-fixed: @base;

        // Links
        --color-progressive: @accent;
        --color-progressive--hover: @bright_teal;
        --color-progressive--active: @teal;
        --color-visited: @purple;
        --color-destructive: @red;
        --color-error: @red;
        --color-warning: @yellow;
        --color-success: @green;

        // Backgrounds
        --background-color-base: @base;
        --background-color-base-fixed: @base;
        --background-color-neutral: @surface0;
        --background-color-neutral-subtle: @mantle;
        --background-color-interactive: @surface0;
        --background-color-interactive--hover: @surface1;
        --background-color-interactive-subtle: @mantle;
        --background-color-interactive-subtle--hover: @surface0;
        --background-color-inverted: @bright_text;

        // Borders
        --border-color-base: @subtext2;
        --border-color-subtle: @surface1;
        --border-color-muted: @surface0;
        --border-color-emphasized: @text;
        --border-color-inverted: @base;
        --border-color-inverted-fixed: @base;

        // Semantic backgrounds
        --background-color-warning-subtle: fade(@yellow, 10%);
        --background-color-error-subtle: fade(@red, 10%);
        --background-color-success-subtle: fade(@green, 10%);
        --background-color-notice-subtle: @surface0;
        --background-color-progressive-subtle: fade(@accent, 10%);
    }

    // --- Page background ---
    body {
        background-color: @mantle;
        color: @text;
    }

    // --- Main content container ---
    .mw-page-container {
        background-color: @base;
    }

    // --- Header ---
    .vector-header-container .mw-header {
        background-color: @base;
    }

    // --- Article title ---
    #firstHeading,
    .firstHeading {
        color: @bright_text;
    }

    // --- Section headings ---
    .mw-heading,
    .mw-heading h1,
    .mw-heading h2,
    .mw-heading h3,
    .mw-heading h4,
    .mw-heading h5,
    .mw-heading h6 {
        color: @bright_text;
    }

    .mw-body-content h2,
    .mw-heading2 {
        border-bottom-color: @surface1;
    }

    // --- Links ---
    a {
        color: @accent;
    }

    a:visited {
        color: @purple;
    }

    a:hover {
        color: @bright_text;
    }

    a.new {
        color: @red;
    }

    a.new:visited {
        color: @red;
    }

    // --- Tabs ---
    .vector-menu-tabs .mw-list-item a {
        color: @subtext0;
    }

    .vector-menu-tabs .mw-list-item a:visited {
        color: @subtext1;
    }

    .vector-menu-tabs .mw-list-item.selected a {
        color: @text;
        border-bottom-color: @accent;
    }

    .vector-menu-tabs .mw-list-item a:hover {
        color: @text;
    }

    // --- Left sidebar ---
    #mw-panel .vector-menu-content a {
        color: @subtext0;
    }

    #mw-panel .vector-menu-content a:visited {
        color: @subtext1;
    }

    #mw-panel .vector-menu-content a:hover {
        color: @accent;
    }

    .vector-menu-heading {
        color: @text;
    }

    // --- Table of Contents ---
    .vector-toc .vector-toc-link {
        color: @subtext0;
    }

    .vector-toc .vector-toc-link:hover {
        color: @accent;
    }

    .vector-toc .vector-toc-list-item-active > .vector-toc-link {
        color: @text;
    }

    .vector-toc .vector-toc-numb {
        color: @subtext1;
    }

    // --- Infoboxes ---
    .infobox {
        background-color: @mantle !important;
        border-color: @surface0 !important;
        color: @text;
    }

    .infobox th,
    .infobox-header {
        background-color: @surface0 !important;
        color: @bright_text;
    }

    .infobox-label {
        color: @subtext0;
    }

    .infobox-data {
        color: @text;
    }

    // --- Wikitables ---
    .wikitable {
        background-color: @mantle;
        color: @text;
        border-color: @surface0;
    }

    .wikitable > tr > th,
    .wikitable > * > tr > th {
        background-color: @surface0;
        color: @bright_text;
        border-color: @surface1;
    }

    .wikitable > tr > td,
    .wikitable > * > tr > td {
        border-color: @surface0;
    }

    // --- Category links ---
    #catlinks {
        background-color: @mantle;
        border-color: @surface0;
        color: @text;
    }

    #catlinks a {
        color: @accent;
    }

    #catlinks a:visited {
        color: @purple;
    }

    // --- Footer ---
    .mw-footer {
        border-top-color: @surface0;
        color: @subtext0;
    }

    .mw-footer li {
        color: @subtext0;
    }

    .mw-footer a {
        color: @subtext0;
    }

    .mw-footer a:hover {
        color: @accent;
    }

    // --- Search box ---
    #searchInput {
        background-color: @surface0;
        color: @text;
        border-color: @surface1;
    }

    #searchInput:focus {
        border-color: @accent;
    }

    .cdx-search-input {
        background-color: @surface0;
        border-color: @surface1;
    }

    .cdx-typeahead-search__search-menu__item:hover {
        background-color: @surface1;
    }

    // --- Thumbnail/image borders ---
    .thumbinner {
        background-color: @mantle;
        border-color: @surface0;
    }

    .thumbcaption {
        color: @subtext1;
    }

    // --- Code blocks ---
    code {
        background-color: @surface0;
        color: @text;
    }

    pre,
    .mw-code {
        background-color: @mantle;
        color: @text;
        border-color: @surface0;
    }

    // --- Blockquotes ---
    blockquote {
        border-left-color: @surface1;
        color: @subtext0;
    }

    // --- Edit sections ---
    .mw-editsection {
        color: @subtext1;
    }

    .mw-editsection a {
        color: @subtext0;
    }

    .mw-editsection a:hover {
        color: @accent;
    }

    // --- "From Wikipedia..." subtitle ---
    #siteSub {
        color: @subtext1;
    }

    // --- Navboxes ---
    .navbox {
        background-color: @mantle;
        border-color: @surface0;
        color: @text;
    }

    .navbox-title {
        background-color: @surface0;
        color: @bright_text;
    }

    .navbox-group {
        background-color: @surface0;
        color: @subtext0;
    }

    .navbox-list {
        background-color: @mantle;
        color: @text;
    }

    .navbox a {
        color: @accent;
    }

    .navbox a:visited {
        color: @purple;
    }

    // --- Ambox / notice boxes ---
    .ambox {
        background-color: fade(@yellow, 10%);
        border-color: @yellow;
    }

    .ambox a {
        color: @accent;
    }

    // --- Redirect categories ---
    .redirectMsg {
        color: @subtext0;
    }

    // --- References ---
    .reference a {
        color: @subtext0;
    }

    .reference a:visited {
        color: @subtext1;
    }

    // --- Diff view ---
    .diff-context {
        background-color: @base;
        color: @text;
    }

    .diff-deletedline {
        background-color: @amber;
        color: @text;
    }

    .diff-addedline {
        background-color: @jade;
        color: @text;
    }

    .diffchange {
        background-color: fade(@accent, 20%);
    }

    // --- Confirm edit / captcha ---
    .mw-confirmaccount-msg {
        color: @subtext0;
    }

    // --- User login / create account ---
    .mw-ui-input {
        background-color: @surface0;
        color: @text;
        border-color: @surface1;
    }

    .mw-ui-input:focus {
        border-color: @accent;
    }

    .mw-ui-button {
        background-color: @accent;
        color: @base;
        border-color: @accent;
    }

    .mw-ui-button:hover {
        background-color: @bright_teal;
        border-color: @bright_teal;
    }
}

/* ==UserStyle==
@name DuckDuckGo Oxide
@namespace github.com/oxidescheme/userstyles/styles/duckduckgo
@homepageURL https://github.com/oxidescheme/userstyles/tree/main/styles/duckduckgo
@version 2025.05.10
@updateURL https://github.com/oxidescheme/userstyles/raw/main/styles/duckduckgo/oxide.user.less
@supportURL https://github.com/oxidescheme/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Aduckduckgo
@description Oxide dark theme for DuckDuckGo
@author Oxide
@license MIT
@preprocessor less
==/UserStyle== */

@import "https://raw.githubusercontent.com/oxidescheme/userstyles/main/lib/lib.less";

@-moz-document domain("duckduckgo.com"), domain("duckduckgogg42xjoc72x3j7ezi56bz3pbi5r4xy72klf2mfdnzf3jad.onion") {
    #lib.palette();
    #lib.defaults();

    // --- CSS custom property overrides (primary theming mechanism) ---
    :root {
        // Theme colors (legacy SERP)
        --theme-col-bg-page: @base;
        --theme-col-bg-header: @base;
        --theme-col-bg-header-transparent: fade(@base, 0);
        --theme-col-bg-search: @surface0;
        --theme-col-txt-search-input: @text;
        --theme-col-txt-search-button: @subtext1;
        --theme-col-txt-title: @accent;
        --theme-col-txt-title-visited: @purple;
        --theme-col-txt-snippet: @subtext0;
        --theme-col-txt-url: @green;
        --theme-col-txt-url-domain: @subtext0;
        --theme-col-txt-url-path: @subtext1;
        --theme-col-txt-card-body: @text;
        --theme-col-txt-card-aside: @subtext1;
        --theme-col-separator: @surface0;
        --theme-col-header-divider: @surface0;
        --theme-searchbox-border: @surface1;
        --theme-col-bg-bar: @mantle;
        --theme-col-bg-modal: @surface0;
        --theme-shadow-card: 0 2px 3px fade(@mantle, 6%);
        --theme-col-icon: @subtext0;
        --theme-col-glow: fade(@accent, 20%);

        // SDS colors (React components)
        --sds-color-background-01: @base;
        --sds-color-background-02: @surface0;
        --sds-color-background-03: @mantle;
        --sds-color-text-01: @text;
        --sds-color-text-02: @subtext0;
        --sds-color-text-03: @subtext1;
        --sds-color-text-link-01: @accent;
        --sds-color-border-inner-divider: fade(@bright_text, 9%);
    }

    // --- Page background ---
    body,
    .site-wrapper {
        background-color: @base !important;
        color: @text !important;
    }

    // --- Header ---
    .header-wrap {
        background-color: @base !important;
    }

    .header__search-wrap {
        background-color: @base;
    }

    // --- Search bar ---
    .search--header {
        background-color: @surface0;
        border-color: @surface1;
    }

    .search--header:hover,
    .search--focus .search--header {
        border-color: @accent;
    }

    .search__input {
        background-color: @surface0;
        color: @text;
    }

    .search__input::placeholder {
        color: @subtext1;
    }

    .search__button {
        background-color: @surface1;
        color: @subtext0;
        border-color: @surface1;
    }

    .search__button:hover {
        background-color: @surface0;
        color: @accent;
    }

    // --- Search suggestions ---
    .search__suggestions {
        background-color: @surface0;
        border-color: @surface1;
    }

    .search__suggestion:hover,
    .search__suggestion--highlighted {
        background-color: @surface1;
    }

    // --- Main content area ---
    .content-wrap {
        background-color: @base;
    }

    .results--main {
        background-color: @base;
    }

    .results--sidebar {
        background-color: @base;
    }

    // --- Search results ---
    .result__a {
        color: @accent !important;
    }

    .result__a:visited {
        color: @purple !important;
    }

    .result__a:hover {
        color: @bright_text !important;
    }

    .result__snippet {
        color: @subtext0 !important;
    }

    .result__url {
        color: @subtext0 !important;
    }

    .result__url__domain {
        color: @green !important;
    }

    .result__url__full {
        color: @subtext1 !important;
    }

    .result__date {
        color: @subtext1 !important;
    }

    .result__extras {
        color: @subtext1;
    }

    .result {
        background-color: @base;
    }

    .result:hover {
        background-color: @mantle;
    }

    // Ad results
    .result--ad .result__a {
        color: @orange !important;
    }

    // Result separator
    .result--sep--hr {
        border-color: @surface0;
    }

    // --- Sidebar / instant answers ---
    .zci-wrap {
        background-color: @surface0;
        border-color: @surface1;
        color: @text;
    }

    .zci__heading {
        color: @text;
    }

    .zci__body {
        color: @subtext0;
    }

    // --- Metabar (tabs) ---
    .metabar {
        background-color: @base;
        border-color: @surface0;
    }

    .metabar__dropdowns {
        color: @subtext0;
    }

    .metabar__dropdowns a {
        color: @subtext0;
    }

    .metabar__dropdowns a:hover {
        color: @accent;
    }

    // --- Footer ---
    .footer {
        background-color: @mantle;
        border-color: @surface0;
        color: @subtext1;
    }

    .footer a {
        color: @subtext0;
    }

    .footer a:hover {
        color: @accent;
    }

    // --- DDG logo (recolored) ---
    .header__logo-wrap svg {
        filter: brightness(0.9);
    }

    // --- Links globally ---
    a {
        color: @accent;
    }

    a:visited {
        color: @purple;
    }

    a:hover {
        color: @bright_text;
    }

    // --- Zero-click info ---
    #zero_click_wrapper {
        background-color: @surface0;
        border-color: @surface1;
        color: @text;
    }

    .zci--type--definitions .zci__content {
        color: @subtext0;
    }

    // --- Buttons ---
    .btn {
        background-color: @surface0;
        color: @text;
        border-color: @surface1;
    }

    .btn:hover {
        background-color: @surface1;
        border-color: @accent;
        color: @accent;
    }

    .btn--primary {
        background-color: @accent;
        color: @base;
    }

    .btn--primary:hover {
        background-color: @bright_teal;
    }

    // --- Dropdown menus ---
    .dropdown {
        background-color: @surface0;
        border-color: @surface1;
    }

    .dropdown__link {
        color: @text;
    }

    .dropdown__link:hover {
        background-color: @surface1;
        color: @accent;
    }
}

/* ==UserStyle==
@name Google Search Oxide
@namespace github.com/oxidescheme/userstyles/styles/google
@homepageURL https://github.com/oxidescheme/userstyles/tree/main/styles/google
@version 2025.05.10
@updateURL https://github.com/oxidescheme/userstyles/raw/main/styles/google/oxide.user.less
@supportURL https://github.com/oxidescheme/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Agoogle
@description Oxide dark theme for Google Search
@author Oxide
@license MIT
@preprocessor less
==/UserStyle== */

@import "https://raw.githubusercontent.com/oxidescheme/userstyles/main/lib/lib.less";

@-moz-document regexp("^https?://(www\\.|images\\.)?google\\..*") {
    #lib.palette();
    #lib.defaults();

    // --- CSS custom property overrides (most maintainable approach) ---
    :root,
    body {
        --xhUGwc: @base;
        --bbQxAb: @text;
        --IXoxUe: @subtext0;
        --COEmY: @text;
        --YLNNHc: @text;
        --JKqx2: @accent;
        --gS5jXb: @surface0;
        --mXZkqc: @surface0;
        --EpFNW: @mantle;
        --XKMDxc: @mantle;
        --TSWZIb: @mantle;
        --gm3-sys-color-primary: @surface0;
        --gm3-sys-color-on-primary: @accent;
    }

    // --- Page background ---
    #gsr,
    body {
        background-color: @base !important;
    }

    .sfbg {
        background-color: @base;
    }

    // --- Header / top bar ---
    .CvDJxb {
        background-color: @base !important;
    }

